CREATE TABLE IF NOT EXISTS misc_schema_version(version TEXT PRIMARY KEY) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS dm_company(id INTEGER PRIMARY KEY,isin TEXT UNIQUE NOT NULL,symbol TEXT UNIQUE NOT NULL,name TEXT,industry TEXT,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS dm_ticker(company_id INTEGER PRIMARY KEY REFERENCES dm_company(id),ticker TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS dm_metric(id INTEGER PRIMARY KEY,statement TEXT NOT NULL,label TEXT NOT NULL,kind TEXT NOT NULL,UNIQUE(statement,label,kind));
CREATE TABLE IF NOT EXISTS dm_period(id INTEGER PRIMARY KEY,frequency TEXT NOT NULL,period_end TEXT NOT NULL,UNIQUE(frequency,period_end));
CREATE TABLE IF NOT EXISTS dm_unit(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS dm_snapshot(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES dm_company(id),retrieved TEXT NOT NULL,sha BLOB NOT NULL,ticker TEXT NOT NULL,provider TEXT NOT NULL DEFAULT 'YAHOO',status TEXT NOT NULL DEFAULT 'STAGING');
CREATE TABLE IF NOT EXISTS ft_financials(id INTEGER PRIMARY KEY,company_id INTEGER NOT NULL REFERENCES dm_company(id),metric_id INTEGER NOT NULL REFERENCES dm_metric(id),period_id INTEGER NOT NULL REFERENCES dm_period(id),unit_id INTEGER NOT NULL REFERENCES dm_unit(id),value_text TEXT NOT NULL,UNIQUE(company_id,metric_id,period_id,unit_id,value_text));
CREATE TABLE IF NOT EXISTS ft_source_reference(fact_id INTEGER NOT NULL REFERENCES ft_financials(id),snapshot_id INTEGER NOT NULL REFERENCES dm_snapshot(id),PRIMARY KEY(fact_id,snapshot_id)) WITHOUT ROWID;
CREATE INDEX IF NOT EXISTS ix_reference_snapshot ON ft_source_reference(snapshot_id);
CREATE TABLE IF NOT EXISTS dm_payload(id INTEGER PRIMARY KEY,sha BLOB UNIQUE NOT NULL,payload BLOB NOT NULL,original_bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ft_extended(snapshot_id INTEGER NOT NULL REFERENCES dm_snapshot(id),module TEXT NOT NULL,payload_id INTEGER NOT NULL REFERENCES dm_payload(id),PRIMARY KEY(snapshot_id,module)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS misc_queue(company_id INTEGER NOT NULL REFERENCES dm_company(id),dataset_group TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',attempts INTEGER NOT NULL DEFAULT 0,last_attempt TEXT,last_success TEXT,next_retry TEXT,error TEXT,PRIMARY KEY(company_id,dataset_group)) WITHOUT ROWID;
CREATE TABLE IF NOT EXISTS misc_quality(snapshot_id INTEGER PRIMARY KEY REFERENCES dm_snapshot(id),report TEXT NOT NULL);
CREATE VIEW IF NOT EXISTS vw_fund_history AS SELECT c.symbol,c.name company_name,m.statement,m.label metric,m.kind,p.frequency,p.period_end,u.code unit,f.value_text native_value,s.id snapshot_id,s.retrieved,s.ticker,'UNKNOWN' reporting_scope,'UNVERIFIED' quality_status FROM ft_financials f JOIN dm_company c ON c.id=f.company_id JOIN dm_metric m ON m.id=f.metric_id JOIN dm_period p ON p.id=f.period_id JOIN dm_unit u ON u.id=f.unit_id JOIN ft_source_reference r ON r.fact_id=f.id JOIN dm_snapshot s ON s.id=r.snapshot_id WHERE s.status='COMPLETE';
CREATE VIEW IF NOT EXISTS vw_fund_observations AS WITH ranked AS (SELECT *,DENSE_RANK() OVER(PARTITION BY symbol,statement,metric,frequency,period_end ORDER BY snapshot_id DESC) rk FROM vw_fund_history) SELECT * FROM ranked WHERE rk=1;
CREATE VIEW IF NOT EXISTS vw_fund_cells AS SELECT symbol,statement,metric,frequency,period_end,MIN(unit) unit,COUNT(DISTINCT unit||':'||native_value) variants,CASE WHEN COUNT(DISTINCT unit||':'||native_value)=1 THEN MAX(CASE unit WHEN 'INR' THEN CAST(native_value AS REAL)/10000000 WHEN 'USD' THEN CAST(native_value AS REAL)/1000000 WHEN 'UNKNOWN' THEN NULL ELSE CAST(native_value AS REAL) END) END display_value FROM vw_fund_observations GROUP BY symbol,statement,metric,frequency,period_end;
CREATE VIEW IF NOT EXISTS vw_fund_acquisition_progress AS SELECT dataset_group,status,count(*) companies FROM misc_queue JOIN dm_company ON id=company_id WHERE active=1 GROUP BY dataset_group,status;
INSERT OR IGNORE INTO misc_schema_version VALUES('6.0');
CREATE VIEW IF NOT EXISTS vw_fund_annual AS SELECT * FROM vw_fund_observations WHERE frequency='ANNUAL';
CREATE VIEW IF NOT EXISTS vw_fund_quarterly AS SELECT * FROM vw_fund_observations WHERE frequency='QUARTERLY';
CREATE VIEW IF NOT EXISTS vw_fund_ttm AS SELECT * FROM vw_fund_observations WHERE frequency='TTM';
CREATE VIEW IF NOT EXISTS vw_fund_growth AS SELECT a.symbol,a.frequency,a.period_end,a.unit,CASE WHEN a.unit=b.unit AND a.unit IN ('INR','USD') AND b.display_value>0 THEN 100.0*(a.display_value/b.display_value-1) END revenue_yoy_pct FROM vw_fund_cells a LEFT JOIN vw_fund_cells b ON a.symbol=b.symbol AND a.frequency=b.frequency AND a.statement=b.statement AND a.metric=b.metric AND b.period_end=date(a.period_end,'-1 year') WHERE a.statement='PNL' AND a.metric='Total Revenue';
